32			cel.Variable("request", cel.DynType),      // Admission request context
33			cel.Variable("authorizer", cel.DynType),   // Authorization context
34			cel.Variable("namespace", cel.StringType), // Current namespace context
35			cel.Variable("cluster", cel.DynType),      // Cluster information
36	
37			// Enable standard CEL extensions for enhanced functionality
38			ext.Strings(),  // String manipulation functions
39			ext.Encoders(), // Base64, URL encoding functions
40			ext.Math(),     // Mathematical functions
41			ext.Lists(),    // List manipulation functions
42			ext.Sets(),     // Set operations
43	
44			// Enhanced Kubernetes-specific functions
45			cel.Function("hasLabel",
46				cel.Overload("hasLabel_string", []*cel.Type{cel.StringType}, cel.BoolType),
47				cel.SingletonUnaryBinding(func(value ref.Val) ref.Val {
48					_ = value.(types.String) // labelKey for future implementation
49					// This would be implemented to check if object has the label
50					return types.Bool(true) // Placeholder
51				})),
52	
53			cel.Function("hasAnnotation",
54				cel.Overload("hasAnnotation_string", []*cel.Type{cel.StringType}, cel.BoolType),
55				cel.SingletonUnaryBinding(func(value ref.Val) ref.Val {
56					_ = value.(types.String) // annotationKey for future implementation
57					// This would be implemented to check if object has the annotation
58					return types.Bool(true) // Placeholder
59				})),
60	
61			cel.Function("isSystemNamespace",
62				cel.Overload("isSystemNamespace_string", []*cel.Type{cel.StringType}, cel.BoolType),
63				cel.SingletonUnaryBinding(func(value ref.Val) ref.Val {
64					ns := string(value.(types.String))
65					systemNamespaces := []string{"kube-system", "kube-public", "kube-node-lease", "default"}
66					for _, sysNs := range systemNamespaces {
67						if ns == sysNs || strings.HasPrefix(ns, "kube-") {
68							return types.Bool(true)
69						}
70					}
71					return types.Bool(false)
72				})),
73	
74			cel.Function("hasSecurityContext",
75				cel.Overload("hasSecurityContext_map", []*cel.Type{cel.DynType}, cel.BoolType),
76				cel.SingletonUnaryBinding(func(value ref.Val) ref.Val {
77					// Check if container has securityContext
78					return types.Bool(true) // Placeholder
79				})),
80	
81			// Enable homogeneous aggregate literals for better type safety
82			cel.HomogeneousAggregateLiterals(),
83	
84			// Enable eager validation for better error reporting
85			cel.EagerlyValidateDeclarations(true),
86	
87			// Set default UTC timezone for consistent time operations
88			cel.DefaultUTCTimeZone(true),
89	
90			// Enable optimizations
91			cel.OptionalTypes(),
92		)
93		if err != nil {
94			return nil, fmt.Errorf("failed to create CEL environment: %w", err)
95		}
96	
97		return &CELEngine{
98			env:      env,
99			matcher:  NewResourceMatcher(),
100			compiler: NewRuleCompiler(),
101		}, nil
102	}
