104	// quickResourceMatch performs a fast pre-filter to check if a resource might match a rule
105	// This avoids expensive CEL compilation and evaluation for obviously non-matching resources
106	func (e *CELEngine) quickResourceMatch(rule *models.SpotterRule, resource map[string]interface{}) bool {
107		// Extract resource metadata
108		apiVersion, _ := resource["apiVersion"].(string)
109		kind, _ := resource["kind"].(string)
110		metadata, _ := resource["metadata"].(map[string]interface{})
111	
112		// Get the kubernetes criteria
113		kubernetesCriteria := rule.Spec.Match.Resources.Kubernetes
114	
115		// Check kind match if specified
116		if len(kubernetesCriteria.Kinds) > 0 {
117			kindMatches := false
118			for _, allowedKind := range kubernetesCriteria.Kinds {
119				if allowedKind == "*" || allowedKind == kind {
120					kindMatches = true
121					break
122				}
123			}
124			if !kindMatches {
125				return false
126			}
127		}
128	
129		// Check API version match if specified
130		if len(kubernetesCriteria.Versions) > 0 {
131			versionMatches := false
132			for _, allowedVersion := range kubernetesCriteria.Versions {
133				if allowedVersion == "*" || apiVersion == allowedVersion {
134					versionMatches = true
135					break
136				}
137				// Also check if the apiVersion contains the version (e.g., "apps/v1" contains "v1")
138				if apiVersion != "" && len(apiVersion) > len(allowedVersion) {
139					if apiVersion[len(apiVersion)-len(allowedVersion):] == allowedVersion {
140						versionMatches = true
141						break
142					}
143				}
144			}
145			if !versionMatches {
146				return false
147			}
148		}
149	
150		// Check API group match if specified
151		if len(kubernetesCriteria.APIGroups) > 0 {
152			groupMatches := false
153			for _, allowedGroup := range kubernetesCriteria.APIGroups {
154				if allowedGroup == "*" {
155					groupMatches = true
156					break
157				}
158				// Core API group is represented as empty string
159				if allowedGroup == "" && (apiVersion == "v1" || !strings.Contains(apiVersion, "/")) {
160					groupMatches = true
161					break
162				}
163				// Check if apiVersion starts with the group
164				if apiVersion != "" && strings.HasPrefix(apiVersion, allowedGroup+"/") {
165					groupMatches = true
166					break
167				}
168			}
169			if !groupMatches {
170				return false
171			}
172		}
173	
174		// Quick namespace check if specified and metadata exists
175		if kubernetesCriteria.Namespaces != nil && metadata != nil {
176			namespace, _ := metadata["namespace"].(string)
177			// Simple include/exclude check - full logic is in MatchesNamespace
178			if len(kubernetesCriteria.Namespaces.Include) > 0 {
179				included := false
180				for _, includePattern := range kubernetesCriteria.Namespaces.Include {
181					if includePattern == "*" || includePattern == namespace {
182						included = true
183						break
184					}
185				}
186				if !included {
187					return false
188				}
189			}
190			if len(kubernetesCriteria.Namespaces.Exclude) > 0 {
191				for _, excludePattern := range kubernetesCriteria.Namespaces.Exclude {
192					if excludePattern == namespace {
193						return false
194					}
195				}
196			}
197		}
198	
199		return true
200	}
201	
202	// EvaluateRule evaluates a single security rule against a single resource
203	func (e *CELEngine) EvaluateRule(ctx context.Context, rule *models.SpotterRule, resource map[string]interface{}) (*models.ValidationResult, error) {
204		result := &models.ValidationResult{
205			RuleID:    rule.GetID(),
206			RuleName:  rule.GetTitle(),
207			Resource:  resource,
208			Severity:  rule.GetSeverityLevel(),
209			Category:  rule.GetCategory(),
210			Timestamp: time.Now(),
211			Passed:    true, // Default to passed
212		}
213	
214		// Check if resource matches rule criteria
215		matches, err := e.matcher.MatchesRule(ctx, rule, resource)
216		if err != nil {
217			return nil, fmt.Errorf("failed to match resource against rule: %w", err)
218		}
219	
220		if !matches {
221			// Resource doesn't match rule criteria, return nil to skip evaluation
222			return nil, nil
223		}
224	
225		// Get compiled program from cache, compile if not cached
226		program, exists := e.compiler.GetCompiled(ctx, rule.GetID())
227		if !exists {
228			// Compile CEL expression if not already compiled
229			if err := e.CompileRule(ctx, rule); err != nil {
230				return nil, fmt.Errorf("failed to compile rule: %w", err)
231			}
232			// Retrieve compiled program after compilation
233			program, exists = e.compiler.GetCompiled(ctx, rule.GetID())
234			if !exists {
235				return nil, fmt.Errorf("failed to retrieve compiled program for rule %s after compilation", rule.GetID())
236			}
237		}
238	
239		celProgram, ok := program.(cel.Program)
240		if !ok {
241			return nil, fmt.Errorf("invalid compiled program type for rule %s", rule.GetID())
242		}
243	
244		// Prepare evaluation context with comprehensive variable set
245		vars := map[string]interface{}{
246			"object":     resource,
247			"oldObject":  nil, // Will be set for update operations
248			"request":    nil, // Will be set for admission controller context
249			"authorizer": nil, // Will be set for authorization context
250		}
251	
252		// Evaluate CEL expression
253		eval, _, err := celProgram.Eval(vars)
254		if err != nil {
255			result.Passed = false
256			result.Message = fmt.Sprintf("CEL evaluation error: %v", err)
257			return result, nil
258		}
259	
260		// Check if evaluation result is a boolean
261		boolResult, ok := eval.Value().(bool)
262		if !ok {
263			result.Passed = false
264			result.Message = fmt.Sprintf("CEL expression must return a boolean value, got %T", eval.Value())
265			return result, nil
266		}
267	
268		// If CEL expression returns true, it means the rule failed (security issue found)
269		result.Passed = !boolResult
270		if !result.Passed {
271			result.Message = fmt.Sprintf("Security rule violation: %s", rule.GetDescription())
272			if rule.GetRemediation() != "" {
273				result.Remediation = rule.GetRemediation()
274			}
275		}
276	
277		return result, nil
278	}
279	
280	// EvaluateRules evaluates multiple rules against a Kubernetes resource
281	func (e *CELEngine) EvaluateRules(ctx context.Context, rules []*models.SpotterRule, resource map[string]interface{}) ([]*models.ValidationResult, error) {
282		results := make([]*models.ValidationResult, 0, len(rules))
283	
284		for _, rule := range rules {
285			select {
286			case <-ctx.Done():
287				return nil, ctx.Err()
288			default:
289			}
290	
291			result, err := e.EvaluateRule(ctx, rule, resource)
292			if err != nil {
293				return nil, fmt.Errorf("failed to evaluate rule %s: %w", rule.GetID(), err)
294			}
295	
296			// Only append results where the resource matches the rule criteria
297			if result != nil {
298				results = append(results, result)
299			}
300		}
301	
302		return results, nil
303	}
