305	// EvaluateRulesAgainstResources evaluates multiple rules against multiple resources
306	func (e *CELEngine) EvaluateRulesAgainstResources(ctx context.Context, rules []*models.SpotterRule, resources []map[string]interface{}) (*models.ScanResult, error) {
307		// Default parallelism
308		return e.EvaluateRulesAgainstResourcesConcurrent(ctx, rules, resources, 10)
309	}
310	
311	// EvaluateRulesAgainstResourcesConcurrent evaluates multiple rules against multiple resources with optimized parallelism
312	func (e *CELEngine) EvaluateRulesAgainstResourcesConcurrent(ctx context.Context, rules []*models.SpotterRule, resources []map[string]interface{}, parallelism int) (*models.ScanResult, error) {
313		startTime := time.Now()
314		allResults := make([]models.ValidationResult, 0)
315		severityBreakdown := make(map[string]int)
316		categoryBreakdown := make(map[string]int)
317		passed := 0
318		failed := 0
319	
320		// Optimize parallelism based on workload
321		numWorkers := parallelism
322		if numWorkers <= 0 {
323			numWorkers = 10 // Default fallback
324		}
325	
326		// Limit workers to avoid over-parallelization for small workloads
327		maxUsefulWorkers := len(rules)
328		if len(resources) < len(rules) {
329			maxUsefulWorkers = len(resources)
330		}
331		if numWorkers > maxUsefulWorkers {
332			numWorkers = maxUsefulWorkers
333		}
334		if numWorkers < 1 {
335			numWorkers = 1
336		}
337	
338		// Pre-filter and batch jobs for better efficiency
339		type ruleResourceBatch struct {
340			rule      *models.SpotterRule
341			resources []map[string]interface{}
342		}
343	
344		type batchResult struct {
345			results []models.ValidationResult
346			err     error
347		}
348	
349		// Group resources by rule for more efficient processing
350		batches := make([]ruleResourceBatch, 0, len(rules))
351		for _, rule := range rules {
352			// Pre-filter resources that might match this rule to reduce unnecessary work
353			matchingResources := make([]map[string]interface{}, 0)
354			for _, resource := range resources {
355				// Quick pre-check based on resource kind/apiVersion if available
356				if e.quickResourceMatch(rule, resource) {
357					matchingResources = append(matchingResources, resource)
358				}
359			}
360			if len(matchingResources) > 0 {
361				batches = append(batches, ruleResourceBatch{
362					rule:      rule,
363					resources: matchingResources,
364				})
365			}
366		}
367	
368		// Use buffered channels sized appropriately
369		batchJobs := make(chan ruleResourceBatch, len(batches))
370		batchResults := make(chan batchResult, len(batches))
371	
372		// Start workers
373		for i := 0; i < numWorkers; i++ {
374			go func() {
375				for batch := range batchJobs {
376					select {
377					case <-ctx.Done():
378						return
379					default:
380					}
381	
382					batchRes := batchResult{results: make([]models.ValidationResult, 0)}
383					for _, resource := range batch.resources {
384						vr, err := e.EvaluateRule(ctx, batch.rule, resource)
385						if err != nil {
386							batchRes.err = err
387							break
388						}
389						if vr != nil {
390							batchRes.results = append(batchRes.results, *vr)
391						}
392					}
393					batchResults <- batchRes
394				}
395			}()
396		}
397	
398		// Send batch jobs
399		go func() {
400			defer close(batchJobs)
401			for _, batch := range batches {
402				select {
403				case <-ctx.Done():
404					return
405				case batchJobs <- batch:
406				}
407			}
408		}()
409	
410		// Collect results
411		for i := 0; i < len(batches); i++ {
412			select {
413			case <-ctx.Done():
414				return nil, ctx.Err()
415			case batchRes := <-batchResults:
416				if batchRes.err != nil {
417					return nil, batchRes.err
418				}
419	
420				for _, result := range batchRes.results {
421					allResults = append(allResults, result)
422					if result.Passed {
423						passed++
424					} else {
425						failed++
426						severityBreakdown[string(result.Severity)]++
427						categoryBreakdown[result.Category]++
428					}
429				}
430			}
431		}
432	
433		return &models.ScanResult{
434			TotalResources:    len(resources),
435			TotalRules:        len(rules),
436			Passed:            passed,
437			Failed:            failed,
438			Results:           allResults,
439			SeverityBreakdown: severityBreakdown,
440			CategoryBreakdown: categoryBreakdown,
441			Timestamp:         startTime,
442			Duration:          time.Since(startTime),
443		}, nil
444	}
