446	// CompileRule pre-compiles a rule's CEL expression for better performance
447	func (e *CELEngine) CompileRule(ctx context.Context, rule *models.SpotterRule) error {
448		// Check if already compiled
449		if _, exists := e.compiler.GetCompiled(ctx, rule.GetID()); exists {
450			return nil
451		}
452	
453		// Parse CEL expression
454		ast, issues := e.env.Parse(rule.GetCELExpression())
455		if issues != nil && issues.Err() != nil {
456			return fmt.Errorf("failed to parse CEL expression: %w", issues.Err())
457		}
458	
459		// Check the AST
460		checked, issues := e.env.Check(ast)
461		if issues != nil && issues.Err() != nil {
462			return fmt.Errorf("failed to check CEL expression: %w", issues.Err())
463		}
464	
465		// Compile the checked expression to a program
466		program, err := e.env.Program(checked)
467		if err != nil {
468			return fmt.Errorf("failed to compile CEL expression: %w", err)
469		}
470	
471		// Cache compiled program
472		return e.compiler.Compile(ctx, rule.GetID(), program)
473	}
474	
475	// ValidateCELExpression validates a CEL expression without caching
476	// This method provides comprehensive validation including syntax, type checking, and semantic analysis
477	func (e *CELEngine) ValidateCELExpression(ctx context.Context, expression string) error {
478		if strings.TrimSpace(expression) == "" {
479			return fmt.Errorf("CEL expression cannot be empty")
480		}
481	
482		// Parse the expression
483		ast, issues := e.env.Parse(expression)
484		if issues != nil && issues.Err() != nil {
485			return fmt.Errorf("syntax error in CEL expression: %w", issues.Err())
486		}
487	
488		// Type-check the expression
489		checked, issues := e.env.Check(ast)
490		if issues != nil && issues.Err() != nil {
491			return fmt.Errorf("type checking failed for CEL expression: %w", issues.Err())
492		}
493	
494		// Validate return type - must be boolean for rule evaluation
495		if !checked.OutputType().IsExactType(cel.BoolType) {
496			return fmt.Errorf("CEL expression must return boolean type for rule evaluation, got %s", checked.OutputType())
497		}
498	
499		// Attempt to compile to catch any compilation issues
500		_, err := e.env.Program(checked)
501		if err != nil {
502			return fmt.Errorf("compilation failed for CEL expression: %w", err)
503		}
504	
505		return nil
506	}
